"""Build bilingual, source-synchronized classroom tutorials."""
from pathlib import Path
from html import escape
import json
from unify_site_shell import apply

ROOT = Path(__file__).resolve().parents[1]
SITE = ROOT / 'linebot-course-site'
SOURCE = SITE / 'examples/reply-bot'
BASE = 'https://andrewshih1210.github.io/my-blog/linebot-course-site/'

def code(text):
    return '<pre tabindex="0"><code>' + escape(text) + '</code></pre>'

def section(id, title, body):
    return f'<section id="{id}"><h2>{title}</h2>{body}</section>'

local = '''node --version
npm test
Copy-Item .env.example .env
# Edit .env locally; never commit it.
node --env-file=.env server.mjs
# In another terminal:
curl.exe http://localhost:8080/healthz'''
deploy = '''# PowerShell: replace YOUR_PROJECT_ID. Billing must be enabled.
$PROJECT = "YOUR_PROJECT_ID"
$REGION = "asia-east1"
$SA = "line-bot-runtime@$PROJECT.iam.gserviceaccount.com"
gcloud auth login
gcloud config set project $PROJECT
gcloud services enable run.googleapis.com cloudbuild.googleapis.com artifactregistry.googleapis.com secretmanager.googleapis.com
gcloud iam service-accounts create line-bot-runtime --display-name="LINE classroom bot runtime"
# First create line-channel-secret and line-channel-access-token in Secret Manager.
# Give each a version 1 containing the real value, without quotes or newlines.
gcloud secrets add-iam-policy-binding line-channel-secret --member="serviceAccount:$SA" --role="roles/secretmanager.secretAccessor"
gcloud secrets add-iam-policy-binding line-channel-access-token --member="serviceAccount:$SA" --role="roles/secretmanager.secretAccessor"
# Run inside the extracted reply-bot directory, not the website repository root.
gcloud run deploy line-classroom-bot --source . --region $REGION --service-account $SA --allow-unauthenticated --max-instances 1 --set-secrets="LINE_CHANNEL_SECRET=line-channel-secret:1,LINE_CHANNEL_ACCESS_TOKEN=line-channel-access-token:1"
gcloud run services describe line-classroom-bot --region $REGION --format="value(status.url)"'''
relay = '''# Create relay-secret version 1 in Secret Manager with the SAME random value
# as GAS Script Properties RELAY_SECRET. Do not use the LINE channel secret.
gcloud secrets add-iam-policy-binding relay-secret --member="serviceAccount:$SA" --role="roles/secretmanager.secretAccessor"
$GAS = "https://script.google.com/macros/s/YOUR_DEPLOYMENT_ID/exec"
gcloud run services update line-classroom-bot --region $REGION --update-env-vars="GAS_LOG_URL=$GAS" --update-secrets="RELAY_SECRET=relay-secret:1"'''

def build(en):
    suffix = '_en' if en else ''
    name = f'quickstart{suffix}.html'
    title = 'Build a replying LINE Bot, then add Sheets logging' if en else '做出會回覆的LINE Bot，再加入Sheets紀錄'
    intro = ('A runnable classroom example with complete source, deployment steps and checks. First send a fixed reply; add signed GAS logging only after that works. No Gemini key is needed.' if en else '從固定文字回覆開始，成功後才加入GAS簽名紀錄。這一頁提供完整原始碼、部署步驟與檢查點，不需要先上磨課師，也不需要Gemini金鑰。')
    body = '<p class="eyebrow">HANDS-ON LAB · 2026-11-07</p><h1>'+title+'</h1><p class="lead">'+intro+'</p>'
    body += '<p><a class="button" href="examples/reply-bot.zip">'+('Download complete example ZIP' if en else '下載完整範例ZIP')+'</a> <a href="#source">'+('Read all source on this page' if en else '直接閱讀完整程式碼')+'</a></p>'
    body += '<aside class="notice">'+('Validation: 12 local automated tests pass using mocked LINE/GAS services. No live LINE account, Cloud Run deployment or real Sheet was tested. The screenshots below are official references, not evidence of our deployment. This is not a production-ready service.' if en else '驗證狀態：12項本機自動測試通過，LINE與GAS外部服務採模擬。尚未使用真實帳戶驗證Cloud Run、LINE回覆及Sheets寫入。下方為官方參考截圖，不是本次帳戶部署成果；此範例也不是可直接上線的正式服務。')+'</aside>'
    labels = [('prepare','01 · '+('Prepare' if en else '準備檔案與帳號')),('line','02 · LINE'),('cloud','03 · Cloud Run'),('webhook','04 · Webhook'),('gas','05 · GAS / Sheets'),('relay','06 · '+('Connect and check' if en else '串接與檢查')),('limits', '07 · '+('Limits' if en else '限制與除錯')),('source', '08 · '+('Source code' if en else '完整程式碼'))]
    body += '<nav class="steps" aria-label="'+('Lesson steps' if en else '實作步驟')+'">'+''.join(f'<a href="#{id}">{label}</a>' for id,label in labels)+'</nav>'
    body += '<div class="flow" aria-label="Architecture">LINE → Node / Cloud Run <strong>'+('verify raw-body signature + reply' if en else '原始本文驗簽＋回覆')+'</strong> → '+('signed minimal record' if en else '簽名最少紀錄')+' → GAS → Sheets</div>'
    body += section('prepare',labels[0][1], ('<ol><li>Install Node.js 22 or later and Google Cloud CLI. Extract the ZIP into a private local folder and open PowerShell in <code>reply-bot</code>.</li><li>Prepare a LINE Official Account, Google account and Google Cloud project with billing. Cloud Run, builds, storage and secrets may incur charges; this is not guaranteed free. Set budget alerts, which are not spending caps.</li><li>Run the tests before adding real secrets. Copy the environment template and edit the two LINE values after step 2. Keep the optional GAS settings commented out for now.</li></ol>' if en else '<ol><li>安裝Node.js 22以上與Google Cloud CLI。解壓縮ZIP到自己的本機資料夾，在<code>reply-bot</code>資料夾開啟PowerShell。</li><li>準備LINE官方帳號、Google帳號，以及已啟用帳務的Google Cloud專案。Cloud Run、建置、儲存及秘密管理可能收費，不保證免費。請設定預算通知，但通知不是費用硬上限。</li><li>先執行測試，不需真實金鑰。複製環境變數範本，完成步驟2後再填入兩個LINE設定；GAS設定先保持註解。</li></ol>')+code(local)+('<p>Expected: 12 passed, no failures or TODOs; <code>/healthz</code> returns <code>ok</code>. A local health check does not connect LINE. GitHub Pages cannot run this Node server.</p>' if en else '<p>預期：12項通過、沒有失敗或TODO；<code>/healthz</code>回傳<code>ok</code>。本機健康檢查不代表已連接LINE。GitHub Pages只能展示教材，不能執行這個Node伺服器。</p>'))
    img1 = '<figure><img loading="lazy" src="https://developers.line.biz/media/messaging-api/verify-webhook-signature/channel-secret-en.png" alt="LINE Developers Basic settings Channel secret reference"><figcaption>'+('Official LINE reference: Basic settings / Channel secret. Interface may change.' if en else 'LINE官方參考截圖：Basic settings／Channel secret。介面可能隨版本調整。')+' <a href="https://developers.line.biz/en/docs/messaging-api/verify-webhook-signature/">'+('Source' if en else '圖片來源')+'</a></figcaption></figure>'
    body += section('line',labels[1][1], ('<ol><li>Create a LINE Official Account. In LINE Official Account Manager, enable Messaging API and choose the correct provider.</li><li>Open the resulting channel in LINE Developers Console. Under Basic settings, retrieve Channel secret; under Messaging API, issue an access token. Limit token lifetime where supported and revoke it after the exercise.</li><li>Put both values in the local <code>.env</code> only for local testing, and in Secret Manager for the cloud deployment. Never paste them into Sheets, screenshots, a public repository or browser JavaScript.</li></ol>' if en else '<ol><li>建立LINE官方帳號，在LINE Official Account Manager啟用Messaging API並選擇正確Provider。</li><li>在LINE Developers Console開啟產生的Channel。Basic settings取得Channel secret；Messaging API頁籤申請Channel access token。可行時使用較短效期，練習結束後撤銷不再使用的Token。</li><li>本機測試時填入自己的<code>.env</code>；雲端部署則放入Secret Manager。不要貼到Sheets、公開截圖、GitHub或瀏覽器JavaScript。</li></ol>')+img1)
    body += section('cloud',labels[2][1], ('<p>In Google Cloud Console → Secret Manager, create <code>line-channel-secret</code> and <code>line-channel-access-token</code>. Paste each value into version 1 without quotes/newlines. Do not pass secrets as plain command-line arguments. The following commands assume you may enable APIs, create service accounts, grant secret access and deploy a public service.</p><p>Source deployment needs Cloud Run Source Developer and Service Usage Consumer permissions for the deployer, Service Account User on the runtime identity, and Cloud Run Builder for the build service account. Organization policies can require an administrator. Do not grant Owner merely to bypass a permission error; consult the linked deployment prerequisites.</p>' if en else '<p>到Google Cloud Console→Secret Manager建立<code>line-channel-secret</code>及<code>line-channel-access-token</code>，各將值貼入第1版，不含引號或換行。不要將秘密直接寫進命令列參數。下列指令假設你有啟用API、建立服務帳戶、授予秘密讀取及部署公開服務的權限。</p><p>原始碼部署需要部署者具備Cloud Run Source Developer、Service Usage Consumer及執行身分的Service Account User權限，建置服務帳戶需要Cloud Run Builder。組織政策可能要求管理員處理；不要為排除錯誤就授予Owner。請核對下方官方部署先備條件。</p>')+code(deploy)+('<p>Use the printed HTTPS service URL plus <code>/healthz</code> to check availability. Only the runtime service account receives access to these specific secrets. Maximum instances of 1 is a classroom setting, not a hard budget or exactly-once guarantee.</p>' if en else '<p>以輸出的HTTPS服務網址加上<code>/healthz</code>檢查，應看到<code>ok</code>。只對執行身分授予指定秘密讀取權限。最大實例設為1是課堂設定，不是費用硬上限或不重複執行保證。</p>'))
    img2 = '<figure><img loading="lazy" src="https://developers.line.biz/media/messaging-api/build-bot/webhook-url-example-com.png" alt="LINE Messaging API Webhook URL Edit Verify reference"><figcaption>'+('Official LINE reference: enter your own HTTPS /webhook URL, not example.com.' if en else 'LINE官方參考截圖：請填自己的HTTPS／webhook網址，不是圖中的example.com。')+' <a href="https://developers.line.biz/en/docs/messaging-api/building-bot/">'+('Source' if en else '圖片來源')+'</a></figcaption></figure>'
    body += section('webhook',labels[3][1], ('<ol><li>Open Messaging API → Webhook settings → Edit. Enter the Cloud Run URL followed by <code>/webhook</code>. Do not enter the GAS URL.</li><li>Select Verify. The empty event request must pass signature verification and return HTTP 200. Enable Use webhook.</li><li>Add the official account as a friend and send text. Expect <code>收到訊息了！Your bot is connected.</code> Disable conflicting automatic replies in Official Account Manager.</li></ol><p>Do not proceed to Sheets until this fixed reply works. An unsigned browser POST should be rejected with 401; do not remove signature verification to make it pass.</p>' if en else '<ol><li>開啟Messaging API→Webhook settings→Edit。填入Cloud Run網址加<code>/webhook</code>，不要填GAS網址。</li><li>按Verify：空事件測試需通過驗簽並回傳HTTP 200，再啟用Use webhook。</li><li>將官方帳號加入好友並傳送文字，預期收到<code>收到訊息了！Your bot is connected.</code>。如出現雙重回覆，檢查Official Account Manager自動回覆設定。</li></ol><p>固定回覆成功後才繼續Sheets。未簽名的POST應被拒絕為401，不可為了讓測試過關而移除驗簽。</p>')+img2)
    body += section('gas',labels[4][1], ('<ol><li>Create a private Google Sheet. Copy its ID between <code>/d/</code> and <code>/edit</code>. Open Extensions → Apps Script and replace the starter code with the complete <code>Code.gs</code> below.</li><li>Project Settings → Script Properties: add <code>SHEET_ID</code> and <code>RELAY_SECRET</code>. Generate a separate random secret with the command below; do not reuse the LINE channel secret. Project editors can read properties, so restrict editing.</li><li>Save, select <code>setupLogSheet</code>, Run, and authorize only the expected account and scopes. Confirm an Events tab with exactly four headers: receivedAt, eventId, type, status.</li><li>Deploy → New deployment → Web app → Execute as yourself → Who has access: Anyone. Copy the <code>/exec</code> URL. If organizational policy forbids this, stop and use an approved backend instead; do not bypass policy.</li><li>After code changes, Deploy → Manage deployments → Edit → New version. Saving code alone does not update the deployed version.</li></ol>' if en else '<ol><li>建立不公開的Google試算表，複製網址<code>/d/</code>與<code>/edit</code>之間的ID。開啟擴充功能→Apps Script，以本頁完整<code>Code.gs</code>取代預設程式。</li><li>專案設定→指令碼屬性新增<code>SHEET_ID</code>及<code>RELAY_SECRET</code>。使用下方指令產生獨立隨機密鑰，不要重用LINE的Channel secret。專案編輯者可以讀取屬性，請限制編輯權限。</li><li>儲存後選取<code>setupLogSheet</code>執行，確認帳號及授權範圍符合預期。試算表應出現Events分頁及四個表頭：receivedAt、eventId、type、status。</li><li>部署→新增部署作業→網頁應用程式→以自己身分執行→誰可以存取：所有人。複製<code>/exec</code>網址。如果組織政策不允許，請停止並改用核准的後端，不可繞過政策。</li><li>修改程式後需至部署→管理部署→編輯→新增版本。只按儲存不會更新已部署版本。</li></ol>')+code('node -e "console.log(require(\'node:crypto\').randomBytes(32).toString(\'hex\'))"')+('<p>Script Properties is not an isolated vault. The public GAS endpoint authenticates the signed body, not the LINE header. Public invocations can still consume execution quota. Keep the Sheet private.</p>' if en else '<p>Script Properties不是獨立保管庫。公開GAS端點驗證的是簽名本文，不是LINE標頭；公開呼叫仍可能消耗執行配額。試算表本身應保持不公開。</p>'))
    body += section('relay',labels[5][1], ('<p>Create <code>relay-secret</code> version 1 in Secret Manager using the same value as GAS. Keep the existing LINE secret bindings; update rather than replace them:</p>' if en else '<p>在Secret Manager建立<code>relay-secret</code>第1版，使用與GAS完全相同的值。保留原有LINE秘密綁定，以下以update方式新增：</p>')+code(relay)+('<ol><li>Send another LINE text. Expect the fixed reply and exactly one Events row with four columns.</li><li>Confirm no message body, LINE user ID or token is stored. Protect event IDs too and define retention.</li><li>If the reply works but the row is absent, inspect <code>GAS_LOG_FAILED</code>, the /exec URL, deployed version, matching relay secrets, Events headers and execution permissions. An HTTP 200 alone is insufficient: GAS JSON must contain <code>ok: true</code>.</li></ol>' if en else '<ol><li>再次傳送LINE文字，應收到固定回覆，Events新增一筆四欄紀錄。</li><li>確認沒有保存訊息本文、LINE使用者ID或Token。事件ID也應限制存取並設定保留期限。</li><li>若有回覆但無紀錄，檢查<code>GAS_LOG_FAILED</code>、/exec網址、部署版本、兩端relay密鑰、Events表頭與執行權限。不能只看HTTP 200，GAS回傳JSON的<code>ok</code>必須是true。</li></ol>'))
    body += section('limits',labels[6][1], ('<ul><li>Node deduplication is in-memory and process-local. Restarts and multiple instances require a durable idempotency design. The sample has no durable queue or exactly-once guarantee.</li><li>After a successful reply, logging failures only emit a warning. A log may be lost; the reply is not repeated to recover logging.</li><li>GAS stops new records at 5,000 rows excluding headers. This is an example guard, not a Google limit. Never just remove it to claim database scalability.</li><li>Move to a database/queue for transactional, high-concurrency or detailed access-control workloads. Measure latency, errors and quota use rather than guessing user counts.</li><li>Keep fixed replies fast. GAS’s 6-minute execution cap is not an acceptable LINE response target. Large files, model calls and long jobs need separate asynchronous design.</li><li>Cleanup: disable the webhook, delete the Cloud Run service and unneeded build artifacts, revoke tokens and unused secret versions, and archive/delete logs according to retention policy.</li></ul>' if en else '<ul><li>Node只做單一程序的記憶體去重；重啟或多實例需要持久化冪等設計。此範例沒有持久化佇列，也不保證exactly-once。</li><li>回覆成功後，紀錄失敗只會警告，可能漏記；不會為補紀錄而重送回覆。</li><li>GAS限制新增紀錄最多5,000筆，不含表頭。這是範例保護值，不是Google上限，不應直接移除後宣稱可當大型資料庫。</li><li>交易、高併發或細緻權限需求應改用資料庫與佇列。以延遲、失敗率及配額實測評估，不用儲存格上限推估使用人數。</li><li>固定回覆應快速完成。GAS單次6分鐘上限不是LINE可接受的回應目標；大型檔案、模型呼叫與耗時任務需另設計非同步處理。</li><li>練習結束：停用Webhook、刪除不需要的Cloud Run服務與建置產物、撤銷Token及未使用的秘密版本，按保留政策封存或刪除紀錄。</li></ul>')+f'<p><a href="apps-script{suffix}.html#security-quotas">'+('Read current quotas, Sheets limits and official sources' if en else '閱讀目前GAS配額、Sheets限制與官方來源')+'</a></p>')
    source = ''
    for filename in ['server.mjs','Code.gs','package.json','Dockerfile','.env.example','.gitignore','.gcloudignore','test.mjs','test-gas.mjs']:
        source += '<details><summary>'+escape(filename)+'</summary>'+code((SOURCE/filename).read_text(encoding='utf-8-sig'))+'</details>'
    body += section('source', labels[7][1], '<p>'+('Generated directly from the downloadable source files; edit the sources and rebuild to keep them synchronized.' if en else '以下直接由可下載的原始碼檔產生，修改範例後重新建置即可同步，避免網頁與下載版內容不同。')+'</p>'+source)
    refs = [('https://developers.line.biz/en/docs/messaging-api/building-bot/','LINE: building a bot'),('https://developers.line.biz/en/docs/messaging-api/verify-webhook-signature/','LINE: signature verification'),('https://cloud.google.com/run/docs/quickstarts/build-and-deploy/deploy-nodejs-service','Cloud Run: Node.js source deployment and IAM'),('https://cloud.google.com/run/docs/configuring/services/secrets','Cloud Run: Secret Manager'),('https://developers.google.com/apps-script/guides/web','Apps Script: web app event fields'),('https://developers.google.com/apps-script/guides/services/quotas?hl=zh-tw','Apps Script: quotas')]
    body += section('references', 'References / '+('Author' if en else '來源與作者'), '<ul>'+''.join(f'<li><a href="{url}">{label}</a></li>' for url,label in refs)+'</ul><p>施育廷 Yu-Ting Shih（Andrew Shih） · '+('Adjunct lecturer, National Taichung University of Education; doctoral candidate, Graduate Institute of Educational Information and Measurement.' if en else '國立臺中教育大學兼任講師、教育資訊與測驗統計研究所博士候選人。')+'</p>')
    schema = {'@context':'https://schema.org','@type':'TechArticle','headline':title,'inLanguage':'en' if en else 'zh-Hant','dateModified':'2026-11-07','author':{'@type':'Person','@id':'https://andrewshih1210.github.io/my-blog/#person','name':'施育廷','alternateName':['Yu-Ting Shih','Andrew Shih']},'url':BASE+name}
    html = f'''<!doctype html>
<html lang="{'en' if en else 'zh-Hant'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title} | LINE Bot Lab</title><meta name="description" content="{escape(intro,quote=True)}">
<link rel="canonical" href="{BASE+name}"><link rel="alternate" hreflang="zh-Hant" href="{BASE}quickstart.html"><link rel="alternate" hreflang="en" href="{BASE}quickstart_en.html">
<link rel="stylesheet" href="quickstart.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body><header><nav><a href="index{suffix}.html">LINE Bot</a><a href="#prepare">{'Start' if en else '開始實作'}</a><a href="#source">{'Source' if en else '程式碼'}</a></nav></header><main class="lab">{body}</main></body></html>'''
    target = SITE/name
    apply(target, html)

if __name__ == '__main__':
    build(False)
    build(True)
    print('Built bilingual tutorials from current example sources.')
